    // The photo variant: the keyed render inside the same viewBox, so the
    // placement CSS and the drift keyframes are shared with the drawing.
    const WHALE_PHOTO_SVG = `
<svg viewBox="0 0 1200 560" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
  <image x="0" y="0" width="1200" height="560" href="data:image/webp;base64,"/>
</svg>
`;

    // The line variant: same 1200x560 viewBox, but it is particles on
    // transparent, so it carries its own placement constant (.aw-whale--lines).
    // Built by tools/photo/lineart.py from the same render.
    const WHALE_LINES_SVG = `
<svg viewBox="0 0 1200 560" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
  <image x="0" y="0" width="1200" height="560" href="data:image/webp;base64,"/>
</svg>
`;

    // The neon variant: an image-to-image pass turned the photo render into
    // particles and a constellation mesh; neon_post.py added the cubes and
    // light filaments around it and keyed the black water to alpha.
    const WHALE_NEON_SVG = `
<svg viewBox="0 0 1200 560" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
  <image x="0" y="0" width="1200" height="560" href="data:image/webp;base64,"/>
</svg>
`;

    const WHALE_MARKUP = WHALE_ART === 'vector'
